func (m *Manager) place(next *bundle.Manifest, fetch []bundle.File, remove []string) error {
	fetched := map[string]bool{}
	for _, f := range fetch {
		fetched[f.Path] = true
	}
	one := func(f bundle.File) error {
		target := m.Target(f.Path)
		if !fetched[f.Path] {
			if fi, err := os.Stat(target); err == nil && fi.Size() == f.Size {
				return nil
			}
