	for _, a := range fleet {
		var cur *store.Bundle
		for _, b := range list {
			if b.Status == v1.RolloutReleased || (b.Status == v1.RolloutCanary && a.Canary) {
				cur = b
				break
			}
		}
		if cur == nil || a.BundleVersion == cur.Version || failedOn(a.UpdateError, "bundle", cur.Version) {
			continue
		}
