"""Exact-match file editing helper: edit(path, [(old, new), ...]). Every old
string must occur exactly once (or `count` times when given as a 3-tuple)."""
import sys

def edit(path, pairs):
    s = open(path).read()
    for p in pairs:
        old, new = p[0], p[1]
        want = p[2] if len(p) > 2 else 1
        got = s.count(old)
        if got != want:
            sys.exit("%s: expected %d match(es), found %d for:\n%s" % (path, want, got, old[:300]))
        s = s.replace(old, new)
    open(path, "w").write(s)
    print("edited", path, "(%d change%s)" % (len(pairs), "" if len(pairs) == 1 else "s"))
