// answerAfterUpload counts a request's response deadline from the last
// byte of its body instead of from its header. The listener's WriteTimeout
// starts when the header is read. A body that took longer than that to
// arrive, like the 16 MB manifest of a bundle or a support bundle on a slow
// site link, was therefore answered after the deadline: the reply was cut
// inside a TLS record, the client reported "bad record MAC", and a publish
// that had gone through looked like a failure.
func answerAfterUpload(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Body != nil && r.Body != http.NoBody {
			r.Body = &uploadBody{ReadCloser: r.Body, ctl: http.NewResponseController(w)}
